<?php namespace App\Filament\Resources\CuratorPlanResource\Pages;use App\Filament\Resources\CuratorPlanResource;use App\Services\PeriodGuard;use Filament\Resources\Pages\CreateRecord;class CreateCuratorPlan extends CreateRecord{protected static string $resource=CuratorPlanResource::class;protected function mutateFormDataBeforeCreate(array $d):array{$p=request()->attributes->get('academic_period');if($p){PeriodGuard::writable($p->id);$d['academic_period_id']=$p->id;}return $d;}}